import React, { useState, useEffect } from "react";
import '../css/AllPages.css';

const MonitorPage = () => {
  const [data, setData] = useState({
    totalTokens: 0,
    totalUsers: 0,
    totalInvited: 0,
    userStats: [],
  });
  const [searchQuery, setSearchQuery] = useState("");
  const [filteredData, setFilteredData] = useState([]);

  // Fetch data from the backend
  const fetchData = async () => {
    try {
      const response = await fetch("https://flask-backend-815i.onrender.com/api/user_stats", {
        method: "GET",
      });

      if (response.ok) {
        const result = await response.json();
        setData({
          totalTokens: result.total_tokens,
          totalUsers: result.total_users,
          totalInvited: result.total_invited,
          userStats: result.user_stats,
        });
      } else {
        console.error("Error fetching data:", response.statusText);
      }
    } catch (error) {
      console.error("Fetch error:", error);
    }
  };

  // Refresh data every 30 seconds
  useEffect(() => {
    fetchData(); // Fetch data on component mount
    const interval = setInterval(fetchData, 30000); // 30-second interval
    return () => clearInterval(interval); // Cleanup on component unmount
  }, []);

  // Filter user data based on search query
  useEffect(() => {
    setFilteredData(
      data.userStats.filter((user) =>
        user.fullname.toLowerCase().includes(searchQuery.toLowerCase())
      )
    );
  }, [searchQuery, data.userStats]);

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Little Fish Token Monitor Page</h1>

      <div style={styles.statsContainer}>
        <div style={styles.statCard}>
          <h2 style={styles.statValue}>{data.totalTokens}</h2>
          <p style={styles.statLabel}>Total Tokens</p>
        </div>
        <div style={styles.statCard}>
          <h2 style={styles.statValue}>{data.totalUsers}</h2>
          <p style={styles.statLabel}>Total Users Joined</p>
        </div>
        <div style={styles.statCard}>
          <h2 style={styles.statValue}>{data.totalInvited}</h2>
          <p style={styles.statLabel}>Total Invites</p>
        </div>
      </div>

      <div style={styles.searchContainer}>
        <input
          type="text"
          placeholder="Search by name..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={styles.searchInput}
        />
      </div>

      <div style={styles.tableContainer}>
        <table style={styles.table}>
          <thead>
            <tr>
              <th style={styles.th}>Name</th>
              <th style={styles.th}>Invited</th>
              <th style={styles.th}>Tokens Earned</th>
            </tr>
          </thead>
          <tbody>
            {filteredData.map((user, index) => (
              <tr key={index} style={styles.tr}>
                <td style={styles.td}>{user.name}</td>
                <td style={styles.td}>{user.invited}</td>
                <td style={styles.td}>{user.tokens}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const styles = {
  container: {
    padding: "20px",
    backgroundColor: "#e0f7fa",
    minHeight: "100vh",
    fontFamily: "MADETOMMY-ExtraBold",
  },
  title: {
    fontSize: "2rem",
    textAlign: "center",
    color: "#0044cc",
    marginBottom: "20px",
    fontFamily: "MADETOMMY-ExtraBold",
  },
  statsContainer: {
    display: "flex",
    justifyContent: "space-between",
    marginBottom: "20px",
    fontFamily: "MADETOMMY-ExtraBold",
  },
  statCard: {
    flex: 1,
    textAlign: "center",
    margin: "0 10px",
    padding: "20px",
    backgroundColor: "#0044cc",
    color: "#ffffff",
    borderRadius: "8px",
    boxShadow: "0 4px 8px rgba(0, 0, 0, 0.1)",
    fontFamily: "MADETOMMY-ExtraBold",
  },
  statValue: {
    fontSize: "1.5rem",
    margin: 0,
  },
  statLabel: {
    fontSize: "1rem",
    margin: 0,
  },
  searchContainer: {
    display: "flex",
    justifyContent: "center",
    marginBottom: "20px",
  },
  searchInput: {
    width: "300px",
    padding: "10px",
    borderRadius: "8px",
    border: "1px solid #ccc",
    fontSize: "1rem",
  },
  tableContainer: {
    maxHeight: "400px",
    overflowY: "auto",
    border: "1px solid #ddd",
    borderRadius: "8px",
    boxShadow: "0 4px 8px rgba(0, 0, 0, 0.1)",
    backgroundColor: "#ffffff",
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
  },
  th: {
    backgroundColor: "#0044cc",
    color: "#ffffff",
    padding: "12px",
    textAlign: "left",
  },
  tr: {
    borderBottom: "1px solid #ddd",
  },
  td: {
    padding: "12px",
    textAlign: "left",
  },
};

export default MonitorPage;
